export function trimmedTotal(dues: string[]): string {
  const figures = dues.filter((d) => d !== NA).map(hundredths).sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
  const kept = figures.length >= 3 ? figures.slice(1, -1) : figures;
  return format(kept.reduce((sum, d) => sum + d, 0n));
}

/** What a claim's late charge follows: the sheet's late percent (two decimals) in force on a date and the
 *  30-day boundaries (yyyy-MM-dd) the claim is overdue past; and whether the claim's live figures round half up (else half to even). */
export type Late = { pct: ((date: string) => string) | undefined; boundaries: (claim: Claim) => string[]; halfUp?: (claim: Claim) => boolean };

/** The sheet's floor (two decimals) in force on a date; undefined for none known. */
export type Floor = ((date: string) => string) | undefined;

/** The late charge on a figure: for every full 30 days overdue, the late percent in force on that boundary
 *  of it, rounded like due, added up (a boundary at 0.00 adds nothing). */
function lateCharge(claim: Claim, figure: string, late: Late | undefined): string | undefined {
  const boundaries = late?.pct === undefined || isCorrection(claim) ? [] : late.boundaries(claim);
  if (boundaries.length === 0 || figure === NA) return undefined;
  const halfUp = late?.halfUp?.(claim) ?? false;
  return format(boundaries.reduce((sum, b) => sum + hundredths(due(figure, late!.pct!(b), halfUp)), 0n));
}

/** Whether the claim keeps a figure whatever the rates: fixed when settled, or bound by a statement to a
 *  figure (bound to n/a keeps no figure). */
const fixed = (claim: Claim) => claim.due !== null || (isBound(claim) && claim.statedDue !== null);

/** A claim's due: the due fixed when it was settled (its late charge frozen in), else its figure — the
 *  rate figure its person's last statement bound it to (not while PENDING), else its amount at the rate in force
 *  on the claim's date of its person's grade in force on that date — plus its late charge when overdue (worked out
 *  on that figure), and at least the sheet's floor in force on the claim's date, applied last.
 *  A correction's live due has no floor and it has no late charge.
function ExportPeople() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const people = usePeople(sheet);
  const claims = useClaims(sheet);
  const rates = useRates(sheet);
  const today = useSheetToday(sheet);
  const settings = useSettings(sheet).data;

  if (!user || !sheet) return null;

  const download = () => {
    const late = lateOf(settings, today);
    const lines = [['name', 'grade', 'retired-from', 'due-total']];
    for (const p of people.data ?? []) {
      const due = personDue(live((claims.data ?? []).filter((c) => c.personId === p.id), [p]), rates.data, p.grades, today, floorOf(settings), late, settings?.cap);
      lines.push([p.name, gradeOn(p.grades, today), p.retiredFrom ?? '', due]);
    }
    const csv = lines.map((l) => l.map(cell).join(',') + '\n').join('');
    const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv' }));
    const a = document.createElement('a');
    a.href = url;
    a.download = `people-${sheet}.csv`;
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  };

  return (
    <p>
      <button type="button" data-testid="export-people" onClick={download}>
        Export people (CSV)
      </button>
    </p>
  );
  const [sheet] = useCurrentSheet();
  const people = usePeople(sheet);
  const claims = useClaims(sheet);
  const periods = usePeriods(sheet);
  const rates = useRates(sheet);
  const today = useSheetToday(sheet);
  const settings = useSettings(sheet).data;
  const floor = floorOf(settings);
  const late = lateOf(settings, today);

  const active = (people.data ?? []).filter((p) => !p.retired);
  const onGrade = (grade: string) => active.filter((p) => gradeOn(p.grades, today) === grade);
  const dueOf = (p: (typeof active)[number]) =>
    personDue(live((claims.data ?? []).filter((c) => c.personId === p.id), [p]), rates.data, p.grades, today, floor, late, settings?.cap);

  const isActiveOn = (p: (typeof active)[number]) =>
    isActive(live((claims.data ?? []).filter((c) => c.personId === p.id), [p]), today);

  return (
    <section data-testid="summary">
      <h2>Summary</h2>
      <table>
        <thead>
          <tr>
            <th>Grade</th>
            <th>People</th>
            <th>Due total</th>
            <th>Active</th>
          </tr>
        </thead>
        <tbody>
function PersonPeriods({ person }: { person: Person }) {
  const [sheet] = useCurrentSheet();
  const periods = usePeriods(sheet);
  const claims = useClaims(sheet);
  const rates = useRates(sheet);
  const today = useSheetToday(sheet);
  const settings = useSettings(sheet).data;
  const late = lateOf(settings, today);
  return (
    <>
      {(periods.data ?? []).map((p) => (
        <td key={p.name} data-testid={`person-period-${p.name}-due-total`}>
          {personPeriodDue(p, person, claims.data, rates.data, floorOf(settings), late)}
        </td>
      ))}
    </>

